### 📝 간단한 풀이 과정

#### 128. Longest consecutive sequence

sort를 이용해서 O(nlogn)까지는 생각하였으나 O(n)의 방법을 찾지 못했습니다...ㅠ
알고보니 비교할때 1씩 더하는걸 이용해서 배열 중 -1이 없는 친구를 찾아가는 아이디어를 쓰면 구현이 쉬웠습니다.
이번주 너무 어렵네요...

```cpp
class Solution {
 public:
  int longestConsecutive(vector<int>& nums) {
    unordered_set<int> numSet(nums.begin(), nums.end());
    int answer = 0;

    for (int num : numSet) {
      // 시작 기준을 해당 수의 - 1이 없으면으로 잡아 while을 돌때 중복을 막는다.
      // (while은 1씩 더해서 확인하므로..)
      if (numSet.find(num - 1) == numSet.end()) {
        int length = 1;

        while (numSet.find(num + length) != numSet.end()) {
          length++;
        }

        answer = max(length, answer);
      }
    }

    return answer;
  }
};
```

#### 371. Sum of two Integers

자연로그를 이용하여 풀고 싶었으나 제곱이 커지면 시간초과가 떠서 결국 비트를 이용하였습니다.
올려줄 자리만 계속 왼쪽으로 옮기고 비교하면서 더하는 곳은 0이 되므로 이용해여 &, ^, <<를 이용하였습니다.

```cpp
class Solution {
 public:
  int getSum(int a, int b) {
    while (b != 0) {
      unsigned int carry = a & b;  // 올려줄 자리 계산
      a = a ^ b;                   // 각 자리 더하기
      b = carry << 1;              // 올려줄 자리를 왼쪽으로 시프트
    }
    return a;
  }
};
```

#### 208. Implement Trie Prefix Tree

직접 풀지 못하고 그래프 부분이 너무 약해서 포인터를 이용하는 cpp를 사용해 이해하려고 노력했습니다.
Trie만 사용하려다 보니 머리가 터졌는데 TrieNode를 따로 만들어 알파벳마다 쭉 노드를 만들어 구현하더라구요.
역시 쉽지 않습니다...

```cpp
class TrieNode {
 public:
  // 알파벳 가르킬 포인터
  TrieNode *child[26];
  // 해당 노드까지 완성된 단어인가 확인
  bool isWord;

  TrieNode() {
    isWord = false;
    for (auto &a : child) a = nullptr;
  }
};

class Trie {
  TrieNode *root;

 public:
  Trie() { root = new TrieNode(); }

  void insert(string s) {
    TrieNode *p = root;

    for (auto &a : s) {
      int i = a - 'a';
      if (!p->child[i]) p->child[i] = new TrieNode();
      p = p->child[i];
    }
    // 다 할당했으면 단어라고 선언, 포인터 변수기 때문에 for문에서 끝까지 할당한
    // 노드에서 isWord가 true
    p->isWord = true;
  }

  bool search(string key, bool prefix = false) {
    TrieNode *p = root;

    for (auto &a : key) {
      int i = a - 'a';
      if (!p->child[i]) return false;
      p = p->child[i];
    }

    // startWith를 위한 prefix 추가, startWith가 아니면 해당 노드가 끝까지
    // 갔는지 isWord만 확인하면 된다.
    if (prefix == false) return p->isWord;

    // startWith라면 해당 노드까지 모두 있는 것이므로 true
    return true;
  }

  bool startsWith(string prefix) { return search(prefix, true); }
};
```

#### 226. Invert Binary Tree

위쪽에서부터 왼쪽, 오른쪽 노드만 바꾸면 되므로 cpp의 swap을 이용했습니다.
다른 사람들 풀이를 보니 아래서부터 올라가던데 아마 위에서부터 내려가면 모든 하위 트리가 옮겨져서 그런 것 같습니다.
결과적으론 0ms로 속도는 똑같은 것 같습니다.

```cpp
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
 public:
  TreeNode* invertTree(TreeNode* root) {
    if (root == nullptr) return nullptr;

    swap(root->left, root->right);

    invertTree(root->left);
    invertTree(root->right);

    return root;
  }
};
```

#### 543. Diameter of Binary Tree

왼쪽 오른쪽 최대 길이만 계산하면 되므로 재귀를 이용하였습니다.
return으로는 최대 길이에 + 1을 반환하고 답은 오른쪽과 왼쪽 노드 길이를 누적하여 비교하면 되므로 max를 이용하였습니다.

```cpp
class Solution {
 public:
  int diameterOfBinaryTree(TreeNode* root) {
    int ans = 0;

    diameter(root, ans);

    return ans;
  }

  int diameter(TreeNode* node, int& ans) {
    if (!node) return 0;

    int left = diameter(node->left, ans);
    int right = diameter(node->right, ans);

    // 오른쪽 왼쪽 diameter 최대치 저장 (left, right는 노드 기준 최대 길이들)
    ans = max(ans, left + right);

    // 최대 길이만 return
    return max(left, right) + 1;
  }
};
```

